# Quantify candidate-object shape correspondences under rotation/reflection.
from itertools import product
A={(0,1),(1,0),(1,1),(1,2)}
B={(0,1),(0,2),(0,3),(1,0),(1,1),(1,2),(1,3)}
C={(0,1),(1,0),(1,1),(1,2)}
D={(0,0),(0,1),(1,0),(1,1)}
def norm(s):
 mr=min(r for r,c in s); mc=min(c for r,c in s);return frozenset((r-mr,c-mc) for r,c in s)
def transforms(s):
 out=set()
 for rot in range(4):
  p=set(s)
  for _ in range(rot):p={(c,-r) for r,c in p}
  for refl in [0,1]:
   z={(r,-c if refl else c) for r,c in p};out.add(norm(z))
 return out
for x in (A,B):
 for y in (C,D):print(len(x),len(y), any(norm(y)==z for z in transforms(x)))
